using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "TimelessCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Any/TimelessCustomDescription", order = 0)]
public class TimelessCustomDescription : CustomBattleActionDescription
{
	private const string timelessID = "Timeless_D";

	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		string text = Smart.Format(base.localizationManager.GetLocalizedString("Timeless_D"), GetFinalAmountWithoutEquation(amountModified));
		string text2 = "";
		TimelessAction timelessAction = battleAction as TimelessAction;
		text2 = Smart.Format(base.localizationManager.GetLocalizedIfYouDo(), timelessAction.SecondAction.GetActionDescription(timelessAction.SecondActionValue).LowercaseFirst());
		return text + "\n" + text2;
	}
}
